<script setup lang="ts">
import { ref } from 'vue'
import { api, post } from '../api'
import LegacyIcon from './LegacyIcon.vue'
import WorkspaceResourcePicker from './WorkspaceResourcePicker.vue'
interface Resources { skills: string[] | null; mcp: string[] | null; knowledge_bases: string[] | null }
interface Row { workspace_id: string; kind: 'system' | 'general' | 'workspace'; follows_root: boolean; display_name: string; path: string; archived: boolean; status: 'ready' | 'invalid'; error: string; instructions?: string; resources?: Resources }
const props = defineProps<{ row: Row; busy?: boolean }>()
const emit = defineEmits<{ saved: [] }>()
const editing = ref(false); const moving = ref(false); const instructionsOpen = ref(false); const resourcesOpen = ref(false)
const name = ref(props.row.display_name); const instructions = ref(props.row.instructions || ''); const destination = ref('')
const resources = ref<Resources>(props.row.resources ?? { skills: null, mcp: null, knowledge_bases: null })
const error = ref('')
const label = props.row.kind === 'system' ? '系统工作区' : props.row.kind === 'general' ? '默认工作区' : props.row.display_name
async function save(body: Record<string, unknown>, close: 'edit' | 'instructions' | 'resources' | 'archive') { error.value = ''; try { await api(`/api/settings/workspace/registrations/${encodeURIComponent(props.row.workspace_id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); if (close === 'edit') editing.value = false; else if (close === 'instructions') instructionsOpen.value = false; else if (close === 'resources') resourcesOpen.value = false; emit('saved') } catch (cause) { error.value = cause instanceof Error ? cause.message : '保存工作区失败' } }
async function migrate() { if (!destination.value.trim()) return; try { await post(`/api/settings/workspace/registrations/${encodeURIComponent(props.row.workspace_id)}/migrate`, { path: destination.value.trim() }); moving.value = false; emit('saved') } catch (cause) { error.value = cause instanceof Error ? cause.message : '迁移失败' } }
function editResources() { Object.assign(resources.value, props.row.resources ?? { skills: null, mcp: null, knowledge_bases: null }); resourcesOpen.value = !resourcesOpen.value }
</script>
<template><article class="workspace-row" :aria-label="label"><div class="workspace-row-heading"><LegacyIcon :name="row.kind === 'system' ? 'settings' : row.kind === 'general' ? 'network' : 'folder'" :size="18" /><h3>{{ label }}</h3><span v-if="row.archived" class="muted">已归档</span><div class="workspace-row-actions"><RouterLink v-if="row.kind !== 'system' && !row.archived && row.status === 'ready'" :to="row.kind === 'general' ? '/chat?dt_workspace=' : `/chat?dt_workspace=${encodeURIComponent(row.workspace_id)}`"><LegacyIcon name="plus" :size="14" />新对话</RouterLink><button v-if="row.kind !== 'system' && !row.archived" @click="editResources"><LegacyIcon name="settings" :size="14" />分配资源</button><button v-if="row.kind !== 'system' && !row.archived" :aria-expanded="instructionsOpen" @click="instructions = row.instructions || ''; instructionsOpen = !instructionsOpen"><LegacyIcon name="document" :size="14" />工作区说明</button><button v-if="row.kind === 'workspace'" aria-label="重命名工作区" @click="name = row.display_name; editing = !editing; moving = false"><LegacyIcon name="edit" :size="14" /></button><button aria-label="迁移目录" @click="moving = !moving; editing = false"><LegacyIcon name="folder" :size="14" /></button><button v-if="row.kind === 'workspace'" :aria-label="row.archived ? '恢复工作区' : '归档工作区'" @click="save({ archived: !row.archived }, 'archive')"><LegacyIcon name="archive" :size="14" /></button></div></div><div class="workspace-row-body"><p v-if="row.kind !== 'workspace'" class="muted">{{ row.kind === 'system' ? '仅保存脱敏配置快照、技能文件和 MCP 清单，API Key 与 Token 仍留在私有配置中。' : '未选择工作区的对话共享此目录中的文件。' }}</p><code>{{ row.path }}</code><p v-if="row.archived" class="muted">已归档，现有会话与文件均保留。</p><form v-if="instructionsOpen" class="workspace-inline-form" @submit.prevent="save({ instructions }, 'instructions')"><label>工作区说明<textarea v-model="instructions" rows="4" placeholder="告诉智能体此工作区的目标、约定和输出要求。" /></label><div><button class="primary">保存</button><button type="button" @click="instructionsOpen = false">取消</button></div></form><form v-if="resourcesOpen" class="workspace-inline-form" @submit.prevent="save({ resources }, 'resources')"><WorkspaceResourcePicker v-model="resources" :workspace-id="row.workspace_id" /><p class="muted">更改会应用于后续轮次，现有会话和文件保留。</p><div><button class="primary">保存</button><button type="button" @click="resourcesOpen = false">取消</button></div></form><form v-if="editing" class="workspace-inline-form" @submit.prevent="save({ name: name.trim() }, 'edit')"><label>工作区名称<input v-model="name" required maxlength="100" autofocus></label><div><button class="primary" :disabled="!name.trim()">保存</button><button type="button" @click="editing = false">取消</button></div></form><form v-if="moving" class="workspace-inline-form" @submit.prevent="migrate"><p class="muted">{{ row.follows_root ? '跟随根目录' : '自定义位置' }}</p><label>新存储目录<input v-model="destination" required placeholder="输入一个尚不存在的目标目录" autofocus></label><p class="muted">复制并验证后再切换，工作区 ID 和会话绑定保持不变，旧目录保留为备份。</p><div><button class="primary" :disabled="!destination.trim()">开始迁移</button><button type="button" @click="moving = false">取消</button></div></form><p v-if="row.error || error" class="error" role="alert">{{ error || row.error }}</p></div></article></template>
